                      `/api/chat/upload?filename=${encodeURIComponent(file.name)}`,
                      { method: "POST", body: file }
                    );

                    if (!response.ok) {
                      const errorData = await response.json();
                      throw new Error(errorData.error || "Erro no servidor de storage");
